// Q4_K/Q5_K only: 512-bit inner loop for the Q8_2_X4 activation. The float
// scale/min epilogue is byte-for-byte the same as mul_mat_qX_K_q8_2_X4_T above,
// so the results are bit-identical; only the integer dots use zmm registers.
template <typename Dequantizer, int nrc_y>
static void mul_mat_qX_K_q8_2_X4_AVX512_T(int n, const void * vx, size_t bx, const DataInfo& info, int nrc_x) {
    assert(n % QK_K == 0);
    const int nb = n / QK_K;

    Q8<nrc_y, block_q8_2_x4> q8(info);

    Dequantizer deq(vx, bx);

    uint32_t utmp[4];
    __m256  accd[nrc_y];
    __m256  scales[2];
    float   d8[8*nrc_y];

    for (int ix = 0; ix < nrc_x; ++ix) {

        for (int iy = 0; iy < nrc_y; ++iy) accd[iy] = _mm256_setzero_ps();

        deq.new_row(ix);

        for (int i = 0; i < nb; ++i) {

            deq.d = GGML_FP16_TO_FP32(deq.x[i].d);
            auto vm = _mm256_cvtph_ps(_mm_set1_epi16(deq.x[i].dmin));
            make_q4_scales(deq.x[i].scales, utmp);
            auto mins = _mm256_mul_ps(vm, _mm256_cvtepi32_ps(_mm256_cvtepu8_epi32(_mm_loadl_epi64((const __m128i *)(utmp + 2)))));
            mins = _mm256_mul_ps(_mm256_set1_ps(-1.f), mins);
            for (int iy = 0; iy < nrc_y; ++iy) {
                auto d4_1 = _mm_cvtepu16_epi32(_mm_loadl_epi64((const __m128i *)(q8.y[iy][2*i+0].d)));
                auto d4_2 = _mm_cvtepu16_epi32(_mm_loadl_epi64((const __m128i *)(q8.y[iy][2*i+1].d)));
                auto dy = _mm256_castsi256_ps(_mm256_slli_epi32(MM256_SET_M128I(d4_2, d4_1), 16));
                _mm256_storeu_ps(d8 + 8*iy, dy);
                auto m4_1 = _mm_cvtepi16_epi32(_mm_loadl_epi64((const __m128i *)(q8.y[iy][2*i+0].d+4)));
                auto m4_2 = _mm_cvtepi16_epi32(_mm_loadl_epi64((const __m128i *)(q8.y[iy][2*i+1].d+4)));
                auto myi  = MM256_SET_M128I(m4_2, m4_1);
                auto my   = _mm256_mul_ps(dy, _mm256_cvtepi32_ps(myi));
                accd[iy]  = _mm256_fmadd_ps(my, mins, accd[iy]);
            }

            auto all_scales = _mm256_mul_ps(_mm256_set1_ps(deq.d), _mm256_cvtepi32_ps(_mm256_cvtepu8_epi32(_mm_loadl_epi64((const __m128i *)utmp))));
            scales[0] = _mm256_set_m128(_mm256_castps256_ps128(all_scales), _mm256_castps256_ps128(all_scales));
            auto scales_h = _mm256_extractf128_ps(all_scales, 1);
            scales[1] = _mm256_set_m128(scales_h, scales_h);

            for (int j = 0; j < QK_K/128; ++j) {

                deq.prepare(i, j);

                for (int iy = 0; iy < nrc_y; ++iy) {
                    const block_q8_2_x4& y = q8.y[iy][2*i+j];
                    auto sumi1 = _mm512_dpbusd_epi32(_mm512_setzero_si512(), deq.bits.values[0], _mm512_loadu_si512((const __m512i*)y.qs+0));
                    auto sumi2 = _mm512_dpbusd_epi32(_mm512_setzero_si512(), deq.bits.values[1], _mm512_loadu_si512((const __m512i*)y.qs+1));
                    auto sumi3 = _mm512_dpbusd_epi32(_mm512_setzero_si512(), deq.bits.values[2], _mm512_loadu_si512((const __m512i*)y.qs+2));
                    auto sumi4 = _mm512_dpbusd_epi32(_mm512_setzero_si512(), deq.bits.values[3], _mm512_loadu_si512((const __m512i*)y.qs+3));
                    sumi1 = _mm512_add_epi32(_mm512_unpacklo_epi32(sumi1, sumi2), _mm512_unpackhi_epi32(sumi1, sumi2));
                    sumi3 = _mm512_add_epi32(_mm512_unpacklo_epi32(sumi3, sumi4), _mm512_unpackhi_epi32(sumi3, sumi4));
                    sumi1 = _mm512_add_epi32(_mm512_unpacklo_epi64(sumi1, sumi3), _mm512_unpackhi_epi64(sumi1, sumi3));
                    auto dy4 = _mm_loadu_ps(d8 + 8*iy + 4*j);
                    auto d4d8 = _mm256_mul_ps(scales[j], _mm256_set_m128(dy4, dy4));
                    accd[iy] = _mm256_fmadd_ps(d4d8, _mm256_cvtepi32_ps(_mm512_castsi512_si256(sumi1)), accd[iy]);
                }

            }

        }

        for (int iy = 0; iy < nrc_y; ++iy) {
            info.store(ix, iy, hsum_float_8(accd[iy]));
        }

    }
}
